local function toHex(c)
	return string.format("#%02X%02X%02X", c.R*255, c.G*255, c.B*255)
end

local isActive = false
local farmBtn = LMG2L["TextButton_e"]
local szInp = LMG2L["TextBox_2f"]
local sttInp = LMG2L["Stt_1c"]
local hookedBoxes = {} -- نتابع الصناديق عشان ما نربط نفس الشيء مرتين

local function hookTextBox(txtBox)
	if hookedBoxes[txtBox] then return end
	hookedBoxes[txtBox] = true

	-- نربط الحدث فوراً
	txtBox.FocusLost:Connect(function(enter)
		if isActive and enter then
			local original = txtBox.Text
			if original ~= "" and not string.find(original, "font") then
				local mainHex = toHex(LMG2L["Color_3"].BackgroundColor3)
				local strokeHex = toHex(LMG2L["St_21"].BackgroundColor3)
				local size = tonumber(szInp.Text) or 0
				local strokeThickness = tonumber(sttInp.Text) or 0

				local tag = '<font color="'..mainHex..'" face="'..selectedFont..'"'
				if size > 0 then tag = tag .. ' size="' .. size .. '"' end
				tag = tag .. '>'

				if strokeThickness > 0 then
					tag = tag .. '<stroke color="'..strokeHex..'" thickness="'..strokeThickness..'">'
				end

				if strokeThickness > 0 then
					txtBox.Text = tag .. original .. '</stroke></font>'
				else
					txtBox.Text = tag .. original .. '</font>'
				end
			end
		end
	end)
end

-- الابتكار الحقيقي: نراقب الفوكس (التركيز) على اللعبة كاملة!
